import type { DrawOp, Subpath } from '@/lib/glyphs/types';
import data from './icons.json';

/**
 * Pictures for the hint words ("avion" ✈️), as vector shapes so they print in the
 * PDF exactly as they look on screen (colour-emoji fonts cannot be embedded).
 * Generated by scripts/build-hint-icons.mjs from Twemoji (CC-BY 4.0).
 */

interface IconShape {
  f: string;
  d: string;
}

const ICONS = (data as { size: number; icons: Record<string, IconShape[]> }).icons;
const BOX = (data as { size: number }).size;

export const ICON_CREDIT = 'Imagini: Twemoji © Twitter / X Corp. și contribuitorii, licență CC-BY 4.0.';
export const ICON_CREDIT_EN = 'Pictures: Twemoji © Twitter / X Corp. and contributors, CC-BY 4.0 licence.';

const cache = new Map<string, { fill: string; subpaths: Subpath[] }[]>();

/** "M1 2L3 4C…Z" (absolute M/L/C/Z only) → subpaths. */
function parsePath(d: string): Subpath[] {
  const tokens = d.match(/[MLCZ]|-?\d*\.?\d+(?:e-?\d+)?/g) ?? [];
  const out: Subpath[] = [];
  let cur: Subpath | null = null;
  let i = 0;
  const num = () => parseFloat(tokens[i++]);
  while (i < tokens.length) {
    const cmd = tokens[i++];
    if (cmd === 'M') {
      cur = { start: { x: num(), y: num() }, segs: [] };
      out.push(cur);
    } else if (cmd === 'L' && cur) {
      cur.segs.push({ kind: 'L', p: { x: num(), y: num() } });
    } else if (cmd === 'C' && cur) {
      const c1 = { x: num(), y: num() };
      const c2 = { x: num(), y: num() };
      cur.segs.push({ kind: 'C', c1, c2, p: { x: num(), y: num() } });
    } else if (cmd === 'Z') {
      cur = null;
    }
  }
  return out;
}

function shapesFor(emoji: string) {
  const hit = cache.get(emoji);
  if (hit) return hit;
  const raw = ICONS[emoji];
  if (!raw) return null;
  const shapes = raw.map((s) => ({ fill: s.f, subpaths: parsePath(s.d) }));
  cache.set(emoji, shapes);
  return shapes;
}

export function hasIcon(emoji: string): boolean {
  return emoji in ICONS;
}

/**
 * Draw-ops for the picture of `emoji`, centred on (cx, cy), `size` mm across.
 * Falls back to the emoji character (screen only) when no picture exists.
 */
export function iconOps(emoji: string, cx: number, cy: number, size: number): DrawOp[] {
  const shapes = shapesFor(emoji);
  if (!shapes) {
    return [{ t: 'text', x: cx, y: cy, text: emoji, size, fill: '#1e3a5f', align: 'center', baseline: 'middle', emoji: true }];
  }
  const scale = size / BOX;
  return [
    {
      t: 'group',
      tx: cx - size / 2,
      ty: cy - size / 2,
      scale,
      ops: shapes.map((s) => ({ t: 'path' as const, subpaths: s.subpaths, fill: s.fill, closed: true })),
    },
  ];
}
